create table cities (id bigint generated by default as identity primary key, name varchar(120) not null unique, time_zone varchar(80) not null);
create table theaters (id bigint generated by default as identity primary key, city_id bigint not null references cities(id), name varchar(120) not null, unique(city_id, name));
create table theater_seats (id bigint generated by default as identity primary key, theater_id bigint not null references theaters(id), label varchar(20) not null, tier varchar(20) not null, unique(theater_id, label));
create table movies (id bigint generated by default as identity primary key, title varchar(200) not null, duration_minutes integer not null);
create table refund_policies (id bigint generated by default as identity primary key, name varchar(120) not null unique, full_refund_hours integer not null, partial_refund_hours integer not null, partial_percent numeric(5,2) not null);
create table discount_codes (id bigint generated by default as identity primary key, code varchar(40) not null unique, percent numeric(5,2) not null, valid_from timestamp with time zone not null, valid_until timestamp with time zone not null, active boolean not null);
create table shows (id bigint generated by default as identity primary key, movie_id bigint not null references movies(id), theater_id bigint not null references theaters(id), refund_policy_id bigint not null references refund_policies(id), starts_at timestamp with time zone not null, regular_price numeric(12,2) not null, premium_price numeric(12,2) not null, weekend_surcharge_percent numeric(5,2) not null);
create index idx_shows_theater_time on shows(theater_id, starts_at);
create index idx_shows_start on shows(starts_at);
create table bookings (id bigint generated by default as identity primary key, show_id bigint not null references shows(id), username varchar(80) not null, status varchar(20) not null, expires_at timestamp with time zone not null, total numeric(12,2) not null, discount_code varchar(40), full_refund_hours integer not null, partial_refund_hours integer not null, partial_percent numeric(5,2) not null, created_at timestamp with time zone not null, confirmed_at timestamp with time zone);
create index idx_bookings_username_created on bookings(username, created_at);
create index idx_bookings_status_expiry on bookings(status, expires_at);
create table show_seats (id bigint generated by default as identity primary key, show_id bigint not null references shows(id), seat_id bigint not null references theater_seats(id), status varchar(20) not null, booking_id bigint references bookings(id), hold_expires_at timestamp with time zone, unique(show_id, seat_id));
create index idx_show_seats_booking on show_seats(booking_id);
create table booking_seats (id bigint generated by default as identity primary key, booking_id bigint not null references bookings(id), seat_id bigint not null references theater_seats(id), label varchar(20) not null, price numeric(12,2) not null, unique(booking_id, seat_id));
create table payments (id bigint generated by default as identity primary key, booking_id bigint not null references bookings(id), outcome varchar(20) not null, amount numeric(12,2) not null, reference varchar(80) not null unique, created_at timestamp with time zone not null);
create index idx_payments_booking on payments(booking_id);
create table refunds (id bigint generated by default as identity primary key, booking_id bigint not null unique references bookings(id), amount numeric(12,2) not null, created_at timestamp with time zone not null);
create table notifications (id bigint generated by default as identity primary key, booking_id bigint not null references bookings(id), username varchar(80) not null, type varchar(20) not null, status varchar(20) not null, created_at timestamp with time zone not null, delivered_at timestamp with time zone, unique(booking_id, type));
create index idx_notifications_username_status on notifications(username, status, created_at);
